	}
	if f.cfg.Namespace == "" {
		f.cfg.Namespace = defaults.Namespace
	}
	if f.cfg.Context == nil {
		f.cfg.Context = context.TODO()
	}
	if f.cfg.Clock == nil {
		f.cfg.Clock = clockwork.NewRealClock()
	}
	if f.ConnPingPeriod == 0 {
		f.ConnPingPeriod = defaults.HighResPollingPeriod
