type cachedCredentials struct {
	tlsConfig *tls.Config
	notAfter  time.Time
}

func (f *Forwarder) getCachedCredentials(ctx authContext) *tls.Config {
	f.Lock()
	defer f.Unlock()
	value, ok := f.credentials.Get(ctx.key())
	if !ok {
		return nil
	}
	creds := value.(*cachedCredentials)
	if creds.notAfter.Before(f.cfg.Clock.Now().Add(time.Minute)) {
		f.credentials.Remove(ctx.key())
		return nil
	}
	return creds.tlsConfig
}

func (f *Forwarder) getOrCreateCredentials(ctx authContext) (*tls.Config, error) {
	if creds := f.getCachedCredentials(ctx); creds != nil {
		return creds, nil
	}
	requestCtx, cancel := f.getOrCreateRequestContext(ctx.key())
	if cancel != nil {
		defer cancel()
		// A previous request may have populated the cache between our first
		// lookup and obtaining the per-key request lock.
		if creds := f.getCachedCredentials(ctx); creds != nil {
			return creds, nil
		}
		creds, err := f.requestCertificate(ctx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		if len(creds.Certificates) == 0 || len(creds.Certificates[0].Certificate) == 0 {
			return nil, trace.BadParameter("auth server returned an empty Kubernetes certificate")
		}
		cert, err := x509.ParseCertificate(creds.Certificates[0].Certificate[0])
		if err != nil {
			return nil, trace.Wrap(err)
		}
		if cert.NotAfter.Before(f.cfg.Clock.Now().Add(time.Minute)) {
			return nil, trace.AccessDenied("Kubernetes certificate expires in less than one minute")
		}
		f.Lock()
		defer f.Unlock()
		ttl := ctx.sessionTTL
		if ttl < time.Second {
			ttl = time.Second
		}
		if err := f.credentials.Set(ctx.key(), &cachedCredentials{tlsConfig: creds, notAfter: cert.NotAfter}, ttl); err != nil {
			return nil, trace.Wrap(err)
		}
		return creds, nil
	}
	// Another request is issuing a CSR for this authentication context.
	select {
	case <-requestCtx.Done():
		creds := f.getCachedCredentials(ctx)
		if creds == nil {
			return nil, trace.BadParameter("failed to request certificate, try again")
		}
		return creds, nil
	case <-f.ctx.Done():
		return nil, trace.BadParameter("forwarder is closing, aborting the request")
	}
}

